// Parser for "WP12 Site Daily Photo Report" PDFs (generated by the WP12 Site Photo Report app, jsPDF).
// Works on text items with positions so it is independent of pdf.js internals.

const MONTHS = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11 };

export const ALIGN = { start: 62700, end: 77508,
  zones: [ { id:'Zone 1', from:62700, to:64800 }, { id:'Zone 2', from:64800, to:68800 },
           { id:'Zone 3', from:68800, to:72350 }, { id:'Zone 4', from:72350, to:77508 } ] };

export function zoneOf(ch){
  if(ch==null) return '';
  for(const z of ALIGN.zones) if(ch>=z.from && ch<=z.to) return z.id;
  return '';
}
export function fmtCh(n){ if(n==null||isNaN(n)) return ''; const k=Math.floor(n/1000), m=Math.round(n-k*1000); return k+'+'+String(m).padStart(3,'0'); }

export async function extractPages(doc){
  const pages=[];
  for(let p=1;p<=doc.numPages;p++){
    const pg=await doc.getPage(p); const tc=await pg.getTextContent();
    const items=[];
    for(const it of tc.items){ const s=(it.str||'').replace(/\s+/g,' ').trim(); if(s) items.push({s,x:it.transform[4],y:it.transform[5]}); }
    pages.push({n:p,items,h:pg.view[3]});
  }
  return pages;
}

function parseDate(s){
  const m=/(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})/.exec(s||''); if(!m) return '';
  const mo=MONTHS[m[2].toLowerCase()]; if(mo==null) return '';
  return m[3]+'-'+String(mo+1).padStart(2,'0')+'-'+String(+m[1]).padStart(2,'0');
}

export function parseChainage(txt){
  const out={ch1:null,ch2:null,side:''};
  if(!txt) return out;
  const m=/CH\s*(\d+)\s*\+\s*(\d{3})(?:\s*-\s*(?:CH\s*)?(\d+)\s*\+\s*(\d{3}))?\s*(LHS|RHS|CL|Both)?/i.exec(txt);
  if(!m) return out;
  out.ch1=+m[1]*1000+ +m[2];
  out.ch2=m[3]!=null ? +m[3]*1000+ +m[4] : out.ch1;
  if(out.ch2<out.ch1){ const t=out.ch1; out.ch1=out.ch2; out.ch2=t; }
  out.side=m[5]?m[5].replace(/^./,c=>c.toUpperCase()).replace(/^Lhs$/i,'LHS').replace(/^Rhs$/i,'RHS').replace(/^Cl$/i,'CL'):'';
  return out;
}

const COLS_DEFAULT=[{k:'no',x:33},{k:'activity',x:64},{k:'bq',x:232},{k:'location',x:311},{k:'structure',x:397},{k:'rfi',x:476}];

function colsFromHeader(items){
  const hdr=items.find(i=>i.s==='ACTIVITY'); if(!hdr) return null;
  const near=(s)=>items.find(i=>Math.abs(i.y-hdr.y)<3 && i.s.startsWith(s));
  const no=near('NO'), bq=near('BQ'), loc=near('LOCATION'), st=near('STRUCTURE'), rfi=near('RFI');
  if(!(no&&bq&&loc&&st&&rfi)) return null;
  return [{k:'no',x:no.x},{k:'activity',x:hdr.x},{k:'bq',x:bq.x},{k:'location',x:loc.x},{k:'structure',x:st.x},{k:'rfi',x:rfi.x}];
}

function rng(t){ const m=/^(\d+)\s*[-–]\s*(\d+)$/.exec(t); if(!m) return [+t]; const a=+m[1],b=+m[2],o=[]; for(let i=a;i<=b&&i-a<50;i++) o.push(i); return o; }
function parseTable(page,cols){
  const hdr=page.items.find(i=>i.s==='ACTIVITY');
  const top = hdr ? hdr.y-12 : 730;
  const body=page.items.filter(i=>i.y<top && i.y>26);
  const colOf=(x)=>{ let c=cols[0].k; for(const cc of cols) if(cc.x<=x+3) c=cc.k; return c; };
  const starts=body.filter(i=>colOf(i.x)==='no' && /^\d{1,3}(?:\s*[-–]\s*\d{1,3})?$/.test(i.s)).sort((a,b)=>b.y-a.y);
  if(!starts.length) return [];
  const rows=starts.map(s=>({no:+s.s.split(/[-–]/)[0],nos:rng(s.s),y:s.y,cells:{activity:[],bq:[],location:[],structure:[],rfi:[]}}));
  for(const it of body){
    const c=colOf(it.x); if(c==='no') continue;
    let r=null; for(const row of rows){ if(row.y>=it.y-3) r=row; else break; }
    if(r) r.cells[c].push(it);
  }
  const join=(arr)=>arr.sort((a,b)=>b.y-a.y||a.x-b.x).map(i=>i.s).join(' ').trim();
  return rows.map(r=>{
    let act=join(r.cells.activity), status='';
    const m=/\[([^\]]*)\]\s*$/.exec(act); if(m){ status=m[1].trim(); act=act.slice(0,m.index).trim(); }
    const dash=(s)=>(s==='-'||s==='–')?'':s;
    return { no:r.no, nos:r.nos, activity:act, status, bq:dash(join(r.cells.bq)), location:dash(join(r.cells.location)),
             structure:dash(join(r.cells.structure)), rfi:dash(join(r.cells.rfi)) };
  });
}

const MAP_NOISE=[/·\s*Zone\s*\d/i,/^Z\d$/,/^\d{2}\+\d{3}$/];
const isNoise=(s)=>MAP_NOISE.some(r=>r.test(s));

function parseCards(page){
  const items=page.items;
  if(!items.some(i=>(i.s==='Status'||i.s==='Location') && i.x<400)) return []; // no-activity photos carry no Status label
  const idx=items.filter(i=>/^\d{2}$/.test(i.s) && ((i.x>30&&i.x<45)||(i.x>300&&i.x<325)) && i.y>250 || /^\d{2}$/.test(i.s) && ((i.x>30&&i.x<45)||(i.x>300&&i.x<325)) && i.y<400);
  const seen=new Set(), cards=[];
  for(const ix of idx){
    const key=ix.x.toFixed(0)+'/'+ix.y.toFixed(0); if(seen.has(key)) continue; seen.add(key);
    const x0=ix.x-3;
    const inCard=items.filter(i=>i!==ix && i.x>=x0-4 && i.x<x0+250 && i.y<ix.y-150 && i.y>=ix.y-330);
    if(!inCard.length) continue;
    const timeIt=inCard.find(i=>/^\d{1,2}:\d{2}$/.test(i.s));
    const rest=inCard.filter(i=>i!==timeIt && !isNoise(i.s));
    const left=rest.filter(i=>Math.abs(i.x-x0)<4).sort((a,b)=>b.y-a.y);
    const title=left[0]; if(!title) continue;
    const labels=left.slice(1);
    const fields={}; const order=[];
    const vals=rest.filter(i=>i.x>x0+30 && i.y<title.y-2).sort((a,b)=>b.y-a.y||a.x-b.x);
    for(const l of labels){ fields[l.s]=[]; order.push(l); }
    for(const v of vals){ let owner=null; for(const l of order){ if(l.y>=v.y-2) owner=l; else break; } if(owner) fields[owner.s].push(v.s); }
    const f={}; for(const k in fields) f[k]=fields[k].join(' ').trim();
    cards.push({ no:+ix.s, x0, yTop:ix.y, title:title.s, time:timeIt?timeIt.s:'', fields:f,
      photo:{ page:page.n, x:x0+17.5, yb:ix.y-196, w:216, h:206 } });
  }
  return cards;
}

export function parseReport(pages, meta={}){
  const warnings=[];
  const p1=pages[0]; if(!p1) throw new Error('Empty PDF');
  const it=p1.items;
  const lab=(s)=>it.find(i=>i.s===s);
  const L=['DATE','TEAM','REPORTED BY','ZONE','WEATHER','REPORT REF. NO.'].map(s=>lab(s)).filter(Boolean);
  if(L.length<5 || !it.some(i=>/SITE DAILY PHOTO REPORT/i.test(i.s))) throw new Error('Not a WP12 Site Daily Photo Report');
  L.sort((a,b)=>a.x-b.x);
  const hdrY=L[0].y, hv={};
  for(const l of L) hv[l.s]=[];
  for(const i of it){ if(i.y<hdrY-4 && i.y>hdrY-20){ let o=null; for(const l of L){ if(l.x<=i.x+2) o=l; } if(o) hv[o.s].push(i); } }
  const hj=(k)=>(hv[k]||[]).sort((a,b)=>a.x-b.x).map(i=>i.s).join(' ').trim();
  const dateTxt=hj('DATE'), repBy=hj('REPORTED BY'), weather=hj('WEATHER'), ref=hj('REPORT REF. NO.');
  const rm=/^(.*?),\s*([A-Za-z]{2,6})$/.exec(repBy);
  const reporter=rm?rm[1].trim():repBy, role=rm?rm[2].toUpperCase():'';
  const am=/AM:\s*(.*?)(?=\s*PM:|$)/i.exec(weather), pm=/PM:\s*(.*)$/i.exec(weather);
  const fm=/WP12-([A-Z0-9]+)-([A-Z0-9]+)-(\d{8})-(\d+)/i.exec(ref||meta.name||'');
  let date=parseDate(dateTxt); if(!date&&fm) date=fm[3].slice(0,4)+'-'+fm[3].slice(4,6)+'-'+fm[3].slice(6,8);
  if(fm && date.replace(/-/g,'')!==fm[3]) warnings.push('Date in report ('+date+') differs from reference no.');
  const foot=pages.flatMap(p=>p.items).find(i=>/Generated with/i.test(i.s));
  const version=foot?(/v([\d.]+)/.exec(foot.s)||[])[1]||'':'';
  const rangeTxt=(it.find(i=>/^Photos from CH/i.test(i.s))||{}).s||'';

  let cols=null, table=[];
  for(const p of pages){
    const c=colsFromHeader(p.items); if(c) cols=c;
    const cardPage=p.items.some(i=>(i.s==='Status'||i.s==='Location')&&i.x<400);
    if(cardPage) continue;
    if(c||(cols&&p.items.some(i=>/^\d{1,3}$/.test(i.s)&&i.x<45&&i.y<730))) table=table.concat(parseTable(p,cols||COLS_DEFAULT));
  }
  const cards=pages.flatMap(p=>parseCards(p));
  const cardByNo=new Map(cards.map(c=>[c.no,c]));
  const items=[];
  const nos=new Set([...table.flatMap(t=>t.nos),...cards.map(c=>c.no)]);
  for(const no of [...nos].sort((a,b)=>a-b)){
    const t=table.find(r=>r.nos.includes(no))||{}; const c=cardByNo.get(no); const f=c?c.fields:{};
    const get=(...ks)=>{ for(const k of ks) if(f[k]) return f[k]; return ''; };
    const loc=t.location||get('Location');
    const pc=parseChainage(loc);
    items.push({
      no, activity:t.activity||(c&&c.title)||'', status:t.status||get('Status'), bq:t.bq||get('Ref.'),
      location:loc, structure:t.structure||get('Structure','Element / point','Element'), rfi:t.rfi||get('RFI'),
      layer:get('Layer / level'), remarks:get('Remarks'), time:c?c.time:'',
      statusBase:'', pct:null, acts:[],
      ch1:pc.ch1, ch2:pc.ch2, side:pc.side, zone:zoneOf(pc.ch1!=null?(pc.ch1+pc.ch2)/2:null),
      photo:c?c.photo:null
    });
  }
  for(const i of items){
    const pm=/(\d+)\s*%/.exec(i.status||''); i.pct=pm?+pm[1]:null;
    i.statusBase=(i.status||'').split(',')[0].replace(/\d+\s*%.*$/,'').trim();
    i.acts=i.activity.split(/\s+\+\s+/).map(a=>a.trim()).filter(Boolean);
  }
  if(!items.length) warnings.push('No activities found');
  if(table.length && cards.length && table.reduce((a,r)=>a+r.nos.length,0)!==cards.length) warnings.push('Activity table ('+table.reduce((a,r)=>a+r.nos.length,0)+') and photo pages ('+cards.length+') do not match');
  return {
    ref:ref||(meta.name||'').replace(/_SDR.*$/i,''), file:meta.name||'', path:meta.path||meta.name||'', size:meta.size||0, mtime:meta.mtime||0,
    date, dateLabel:dateTxt, team:hj('TEAM'), reporter, role, code:fm?fm[2].toUpperCase():'', seq:fm?+fm[4]:1,
    zoneLabel:hj('ZONE'), weatherAM:am?am[1].trim():'', weatherPM:pm?pm[1].trim():'', weatherRaw:weather,
    version, pages:pages.length, range:rangeTxt, items, warnings
  };
}

// ---- Data embedded by WP12 Site Photo Report v1.2.6+ in the PDF "Keywords" property: "WP12SDR1:" + flag + base64url(zlib(JSON))
export async function decodeEmbedded(keywords){
  const m=/^WP12SDR(\d+):(.+)$/s.exec(keywords||''); if(!m) return null;
  try{
    const flag=m[2][0]; let b=m[2].slice(1).replace(/-/g,'+').replace(/_/g,'/'); while(b.length%4) b+='=';
    const bin=Uint8Array.from(atob(b),c=>c.charCodeAt(0));
    let raw=bin;
    if(flag==='1'){ const ds=new DecompressionStream('deflate'); const w=ds.writable.getWriter(); w.write(bin); w.close(); raw=new Uint8Array(await new Response(ds.readable).arrayBuffer()); }
    const j=JSON.parse(new TextDecoder().decode(raw)); return j&&j.e?j.e:null;
  }catch(e){ return null; }
}
const chNum=(s)=>{ const m=/^(\d+)\+(\d{3})$/.exec((s||'').trim()); return m? +m[1]*1000+ +m[2] : null; };
export function applyEmbedded(report, e){
  if(!e||!Array.isArray(e.photos)) return report;
  report.source='embedded';
  if(e.team) report.team=e.team;
  for(const p of e.photos){
    let it=report.items.find(i=>i.no===p.no);
    if(!it){ it={no:p.no,activity:'',status:'',bq:'',location:'',structure:'',rfi:'',layer:'',remarks:'',time:'',statusBase:'',pct:null,acts:[],ch1:null,ch2:null,side:'',zone:'',photo:null}; report.items.push(it); }
    const set=(k,v)=>{ if(v!=null && String(v).trim()!=='') it[k]=String(v).trim(); };
    set('activity',p.actEN); set('bq',p.bq); set('structure',p.struct); set('layer',p.el); set('remarks',p.rem); set('time',p.time);
    set('status',p.status);
    if(p.rfi && !(it.rfi||'').includes(p.rfi)) it.rfi=p.rfi;
    const a=chNum(p.ch), b=chNum(p.ch2)??a;
    if(a!=null){ it.ch1=Math.min(a,b); it.ch2=Math.max(a,b); it.side=p.side||it.side; it.zone=zoneOf((a+b)/2);
      it.location='CH '+p.ch+(p.ch2?' - '+p.ch2:'')+(p.side?' '+p.side:''); }
    it.file=p.file||''; it.place=p.place||''; it.dwg=p.dwg||''; it.result=p.result||''; it.gps=(p.lat&&p.lon)?{lat:+p.lat,lon:+p.lon,ch:p.gch||''}:null;
    const pg=parseFloat(String(p.prog||'').replace('%','')); it.pct=isFinite(pg)?pg:it.pct;
    it.statusBase=(it.status||'').split(',')[0].replace(/\d+\s*%.*$/,'').trim();
    it.acts=(it.activity||'').split(/\s+\+\s+/).map(x=>x.trim()).filter(Boolean);
  }
  report.items.sort((a,b)=>a.no-b.no);
  if(e.rfis) report.rfis=e.rfis;
  return report;
}
